        var all = mcpParse(github_list_workflow_runs({
            workspace: repoInfo.owner, repository: repoInfo.repo, perPage: 50
        })) || {};
        var allList = all.workflow_runs || all.workflowRuns || [];
        var want = '.github/workflows/' + ciWorkflow;
