};

function conclusionForOutcome(outcome) {
   return CYCLE_OUTCOME_CONCLUSIONS.hasOwnProperty(outcome) ? CYCLE_OUTCOME_CONCLUSIONS[outcome] : null;
}

// AC1 state machine: {state:'open'} + outcome → {state:'closed', conclusion}
function closePlaceholderCycle(cycle, outcome) {
   var conclusion = conclusionForOutcome(outcome);
