  let d=0, line=1; const out=[];
  let instr=null, esc=false, inlc=false, inbc=false;
  for(let i=0;i<s.length;i++){
    const c=s[i], n=s[i+1];
    if(c==='\n'){line++; inlc=false; continue;}
    if(inlc) continue;
    if(inbc){ if(c==='*'&&n==='/'){inbc=false;i++;} continue;}
    if(instr){ if(esc){esc=false;} else if(c==='\\'){esc=true;} else if(c===instr){instr=null;} continue;}
    if(c==='/'&&n==='/'){inlc=true;i++;continue;}
    if(c==='/'&&n==='*'){inbc=true;i++;continue;}
    if(c==='"'||c==="'"||c==='`'){instr=c;continue;}
    if(c==='{') d++;
    if(c==='}'){ d--; out.push(d+ '@' + line); }
  }
  return {out, d};
}
