  var HEAD = '23dacd10deadbeefcafe0123456789abcdef0123';
  var T0 = '2026-10-09T04:01:00.000Z';
  var T0_MS = Date.parse(T0);
  var LEG_WF = '.github/workflows/ai-teammate.yml';

