    var input = {
      repoInfo: { owner: 'acme', repo: 'factory' },
      prs: [], mergedPrs: [], issues: [], runs: [],
      now: T0
    };
    if (extra) {
      Object.keys(extra).forEach(function (k) { input[k] = extra[k]; });
    }
