      prev: prev,
      reworkInFlight: { ['pr-1429@' + HEAD2]: { head: HEAD2, at: T0 } }
    }));
    assert.ok(state.reworkInFlight['pr-1428@' + HEAD], 'prev entry kept');
    assert.ok(state.reworkInFlight['pr-1429@' + HEAD2], 'live entry merged');
