    var prev = { lanes: {}, reworkInFlight: { ['pr-1428@' + HEAD]: { head: HEAD, at: T0 } } };
    var state = fsModule.buildFactoryState(baseInput({
      prev: prev,
      now: '2026-10-09T05:00:00.000Z'
    }));
    assert.deepEqual(state.reworkInFlight, {}, 'stale latch self-heals');
  });

