suite('factoryState — zombiesSwept (gh-998 leak-rate metric)', function () {
  var T0 = '2026-10-17T19:00:00.000Z';

  function baseInput(extra) {
    var input = {
      repoInfo: { owner: 'acme', repo: 'factory' },
